def merge_intervals(intervals):
    if not intervals:
        return []

    # Sort intervals by start time
    sorted_intervals = sorted(intervals, key=lambda x: x[0])

    merged = [sorted_intervals[0]]

    for current_start, current_end in sorted_intervals[1:]:
        last_start, last_end = merged[-1]

        if current_start <= last_end:
            # Overlapping or touching intervals - merge them
            merged[-1] = [last_start, max(last_end, current_end)]
        else:
            # Non-overlapping interval - add it to merged list
            merged.append([current_start, current_end])

    return merged

def toposort(nodes, edges):
    # Build adjacency list and in-degree count
    graph = {node: [] for node in nodes}
    in_degree = {node: 0 for node in nodes}

    # Process edges to build graph and calculate in-degrees
    for source, dest in edges:
        if source == dest:
            raise ValueError("Cycle detected")
        graph[source].append(dest)
        in_degree[dest] += 1

    # Find all nodes with zero in-degree
    queue = sorted([node for node in nodes if in_degree[node] == 0])
    result = []

    # Process nodes in topological order
    while queue:
        # Get the lexicographically smallest node
        current = queue.pop(0)
        result.append(current)

        # Reduce in-degree of neighbors
        for neighbor in graph[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # Check if all nodes were processed (no cycles)
    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError

    current_batch = []
    all_batches = []
    current_weight = 0

    for name, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError
        if current_weight + weight > limit:
            if current_batch:
                all_batches.append(current_batch)
            current_batch = [name]
            current_weight = weight
        else:
            current_batch.append(name)
            current_weight += weight

    if current_batch:
        all_batches.append(current_batch)

    return all_batches

def parse_sse(chunks):
    data_lines = []
    buffer = b""
    events = []

    for chunk in chunks:
        buffer += chunk
        lines = buffer.split(b'\n')
        buffer = lines[-1]

        for line in lines[:-1]:
            if line.endswith(b'\r'):
                line = line[:-1]

            if not line:
                if data_lines:
                    events.append('\n'.join(data_lines))
                    data_lines = []
            else:
                line_str = line.decode('utf-8', errors='ignore')
                if line_str.startswith('data:'):
                    data_content = line_str[5:].lstrip()
                    data_lines.append(data_content)

    # Handle remaining buffer
    if buffer and not buffer.endswith(b'\n') and data_lines:
        # Check if the last line is a data line that needs to be processed
        try:
            last_line = buffer.decode('utf-8', errors='ignore')
            if last_line.startswith('data:'):
                data_content = last_line[5:].lstrip()
                data_lines.append(data_content)
        except:
            pass

    # Final processing for any remaining data
    if data_lines:
        events.append('\n'.join(data_lines))

    # Filter out events with [DONE]
    result = []
    for event in events:
        if event == "[DONE]":
            break
        if event:
            result.append(event)

    return result

def retry_delay(attempt, base, cap):
    if attempt < 0 or base < 0 or cap < 0:
        raise ValueError("Negative arguments not allowed")

    if attempt >= 10**9:
        # Handle large attempt values without overflow
        # 2^(10^9) is astronomically large, so we just cap it at cap
        return float(cap)

    # For attempt < 10^9, compute base * 2^attempt safely
    if base == 0:
        return 0.0

    if cap == 0:
        return 0.0

    # Use exponentiation by squaring to avoid overflow for large exponents
    # but since we're limited by the cap and attempt can be up to 10^9,
    # we can compute it directly in Python which handles big integers well
    result = base * (2 ** attempt)

    return float(min(cap, result))
